<script setup>
import { ref, reactive, computed, watch, onMounted, onBeforeUnmount } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { erosionApi } from '@/api/wellboreErosion'
import { sandProductionApi } from '@/api/sandProduction'
import { liquidLoadingApi } from '@/api/wellboreRisk'
import { constraintRecordApi, scopeKey } from '@/api/solutionGeneration'
import { ElImage } from 'element-plus'

// 井身结构的字段配置直接写在本组件，不引用外部配置文件。
// 管柱结构展示规则：按原平台 7 种井身结构截图还原。
// 该文件只负责界面字段显隐与顺序，不包含井筒流动计算假设。
const WELLBORE_STRUCTURES = Object.freeze([
  '情况1', '情况2', '情况3', '情况4', '情况5', '情况6', '情况7'
])

const field = (key, label, column, row) => Object.freeze({ key, label, column, row })

const common = Object.freeze([
  field('mdDepth', '当前产层中深（MD）(m)', 2, 1),
  field('tvdDepth', '当前产层中深（TVD）(m)', 3, 1),
  field('casingInnerDiameter', '生产套管内径(mm)', 1, 2)
])
const tubing = Object.freeze([
  field('tubingMdDepth', '油管下深（MD）(m)', 2, 2),
  field('tubingTvdDepth', '油管下深（TVD）(m)', 3, 2),
  field('tubingInnerDiameter', '油管内径(mm)', 1, 3)
])
const chokeWithTubing = Object.freeze([
  field('chokeMdDepth', '节流器下深（MD）(m)', 2, 3),
  field('chokeTvdDepth', '节流器下深（TVD）(m)', 3, 3),
  field('chokeInnerDiameter', '节流器内径(mm)', 1, 4)
])
const chokeWithoutTubing = Object.freeze([
  field('chokeMdDepth', '节流器下深（MD）(m)', 2, 2),
  field('chokeTvdDepth', '节流器下深（TVD）(m)', 3, 2),
  field('chokeInnerDiameter', '节流器内径(mm)', 1, 3)
])
const velocityPipe = Object.freeze([
  field('velocityPipeMdDepth', '速度管柱下深（MD）(m)', 2, 2),
  field('velocityPipeTvdDepth', '速度管柱下深（TVD）(m)', 3, 2),
  field('velocityPipeInnerDiameter', '速度管柱内径(mm)', 1, 3)
])

const fieldsByStructure = Object.freeze({
  '情况1': [...common, ...tubing, ...chokeWithTubing],
  '情况2': [...common, ...tubing],
  '情况3': [...common, ...tubing, ...chokeWithTubing],
  '情况4': [...common, ...tubing],
  '情况5': [...common, ...chokeWithoutTubing],
  '情况6': [...common],
  '情况7': [...common, ...velocityPipe]
})

function getWellboreFields(structure) {
  if (!Object.prototype.hasOwnProperty.call(fieldsByStructure, structure)) {
    throw new Error(`不支持的井身结构：${String(structure)}`)
  }
  // 不直接修改缓存的字段数组，以免切换后出现位置串扰。
  return fieldsByStructure[structure].map(item => ({ ...item }))
}

function hasTubing(structure) {
  return ['情况1', '情况2', '情况3', '情况4'].includes(structure)
}

const props = defineProps({
  projectId: { type: [Number, String], required: true },
  gasReservoirId: { type: [Number, String], required: true },
  wellName: { type: String, required: true },
  // 通过左侧历史方案节点打开时，由父组件传入真实数据库ID。
  recordId: { type: [Number, String], default: null }
})
const emit = defineEmits(['constraints-calculated', 'constraints-invalidated'])

const formData = reactive({
  gasProperties: {
    gasType: '干气', dless: '0.58', h2sContent: '4.62',
    co2Content: '3.96', n2Content: '0'
  },
  calcMethod: {
    correctionMethod: 'Wichert-Aziz 修正方法',
    deviationMethod: 'Dranchuk-Abu-Kassem 方法',
    viscosityMethod: 'Lee-Gonzalez-Eakin 方法'
  },
  pipeData: {
    wellboreStructure: '情况1', mdDepth: '3596.95', tvdDepth: '3575.11',
    casingInnerDiameter: '124.46', tubingMdDepth: '3516.8',
    tubingTvdDepth: '3504.47', tubingInnerDiameter: '57.72',
    chokeMdDepth: '0', chokeTvdDepth: '0', chokeInnerDiameter: '0',
    velocityPipeMdDepth: '0', velocityPipeTvdDepth: '0', velocityPipeInnerDiameter: '0',
    casingMdDepth: '',    // 需要添加 - 套管下深MD
    casingTvdDepth: '',   // 需要添加 - 套管下深TVD
  },
  otherData: {
    coefficientA: '3.1477E-2', coefficientB: '1.6793E-5',
    initialPressure: '50', reservoirTemperature: '80', wellheadTemperature: '20',
    dynamicReserve: '24.4552', productionRate: '31.5058',
    cumulativeProduction: '13.1084', materialBalanceType: '定容气藏',
    targetProduction: '31.5058', forecastStartDate: '2014-01-15',
    forecastTimeStep: '30', forecastTotalDays: '240',
    wellheadExportPressure: '9', abandonmentRate: '4'
  }
})

const structureImages = Object.freeze({
  '情况1': 'data:image/png;base64,', '情况2': 'data:image/png;base64,', '情况3': 'data:image/png;base64,',
  '情况4': 'data:image/png;base64,', '情况5': 'data:image/png;base64,',
  '情况6': 'data:image/png;base64,', '情况7': 'data:image/png;base64,'
})
const visiblePipeFields = computed(() => getWellboreFields(formData.pipeData.wellboreStructure))
const structureImage = computed(() => structureImages[formData.pipeData.wellboreStructure])
const structurePreviewImages = computed(() => structureImage.value ? [structureImage.value] : [])
const currentStructureHasTubing = computed(() => hasTubing(formData.pipeData.wellboreStructure))
const noTubingMessage = computed(() => currentStructureHasTubing.value
  ? '' : `${formData.pipeData.wellboreStructure}没有油管，无法计算约束条件`)

const isCalculating = ref(false)
const saving = ref(false)
const saveFeedbackVisible = ref(false)
const calculationResults = ref(null)
const calculationMeta = ref(null)
const actualAlgorithmRequests = ref(null)
const lastCalculatedSignature = ref(null)
let restoringRecord = false
let historyRequestVersion = 0
let recordLoadVersion = 0
const constraintHistory = ref([])
const historyError = ref('')
const historyLoading = ref(false)
const currentRecordId = ref(null)
const historyVisible = ref(false)
const currentRecordName = ref(null)
const selectedConstraints = reactive({
  erosionLimit: true, sandProductionLimit: true, liquidLoadingLimit: true
})
const selectedKeys = ['erosionLimit', 'sandProductionLimit', 'liquidLoadingLimit']
const initialFormData = JSON.parse(JSON.stringify(formData))
// 当前页面的天然气组分和物性方法作为方案输入保存。冲蚀、积液算法
// 则各自使用其专业服务实际采用的 PVT；页面字段不会隐式覆盖该 PVT。
const pvtInputSignature = () => JSON.stringify({ ...formData.gasProperties, ...formData.calcMethod })
let calculationPvtBaseline = pvtInputSignature()
function acceptCurrentPvtAsBaseline() {
  calculationPvtBaseline = pvtInputSignature()
}
const pvtNeedsSync = computed(() => pvtInputSignature() !== calculationPvtBaseline)

let requestVersion = 0
let runningCalculationSignature = null
let unmounted = false

const scope = () => ({
  projectId: Number(props.projectId),
  gasReservoirId: Number(props.gasReservoirId),
  wellName: props.wellName
})
// 每口井独立记住最后选择的井身结构，避免返回页面时重新落回默认选项。
const structureSelectionKey = () => `grdp:wellbore-structure:v1:${scopeKey(scope())}`
function restoreWellboreStructure() {
  if (typeof window === 'undefined') return
  let selected = null
  try {
    selected = window.sessionStorage.getItem(structureSelectionKey())
    if (!WELLBORE_STRUCTURES.includes(selected)) {
      const key = `grdp:constraints-saved:v1:${props.projectId}:${props.gasReservoirId}:${encodeURIComponent(props.wellName || '')}`
      const saved = JSON.parse(window.sessionStorage.getItem(key) || 'null')
      if (saved && String(saved.projectId) === String(props.projectId) &&
          String(saved.gasReservoirId) === String(props.gasReservoirId) &&
          saved.wellName === props.wellName) {
        selected = saved.inputs?.pipeData?.wellboreStructure
      }
    }
  } catch (error) {
    console.warn('[约束条件] 无法读取已选井身结构', error)
  }
  formData.pipeData.wellboreStructure = WELLBORE_STRUCTURES.includes(selected) ? selected : '情况1'
}
const parseJson = value => {
  if (typeof value !== 'string') return value
  try { return JSON.parse(value) } catch { return null }
}
const unwrap = value => {
  let current = parseJson(value)
  for (let i = 0; i < 3 && current && typeof current === 'object' &&
    !Array.isArray(current) && Object.prototype.hasOwnProperty.call(current, 'data'); i++) {
    current = parseJson(current.data)
  }
  return current
}
const asNumber = (value, label, { zero = false, temperature = false } = {}) => {
  if (value == null || String(value).trim() === '' || !Number.isFinite(Number(value))) {
    throw new Error(`${label}不是有效数字`)
  }
  const n = Number(value)
  if (temperature ? n <= -273.15 : (zero ? n < 0 : n <= 0)) {
    throw new Error(`${label}超出允许范围`)
  }
  return n
}
const optionalNumber = value => value == null || value === '' || !Number.isFinite(Number(value))
  ? null : Number(value)
const positive = value => {
  const n = optionalNumber(value)
  return n !== null && n > 0 ? n : null
}

function syncTargetProductionFromObjective() {
  try {
    const key = `grdp:objective:v1:${props.projectId}:${props.gasReservoirId}:${encodeURIComponent(props.wellName || '')}`
    const raw = window.sessionStorage.getItem(key)
    if (!raw) return
    const parsed = JSON.parse(raw)
    if (parsed?.demandQ != null && parsed.demandQ !== '') {
      formData.otherData.targetProduction = String(parsed.demandQ)
    }
  } catch { /* ignore */ }
}
function onObjectiveSaved(event) {
  const { demandQ, wellName } = event.detail || {}
  if (wellName === props.wellName && demandQ != null && demandQ !== '') {
    formData.otherData.targetProduction = String(demandQ)
  }
}

const errorText = error =>
  error?.response?.data?.msg ||
  error?.response?.data?.message ||
  error?.msg || error?.message || '算法接口未返回有效结果'

const clone = value => JSON.parse(JSON.stringify(value))
function snapshotFormData() {
  // 取保存按钮点击时正在编辑的值，而不是计算前缓存或表单默认值。
  const snapshot = clone(formData)
  const activeKeys = new Set(['wellboreStructure', ...visiblePipeFields.value.map(field => field.key)])
  for (const key of Object.keys(snapshot.pipeData)) {
    if (!activeKeys.has(key)) delete snapshot.pipeData[key]
  }
  return snapshot
}

// 本次已计算结果实际依赖的输入；改变这些参数必须重新计算。
// 不直接影响三个气量模型的目标产量、时间步长等输入可以原值保存。
function calculatedInputSignature() {
  const other = formData.otherData
  return JSON.stringify({
    gasProperties: formData.gasProperties,
    calcMethod: formData.calcMethod,
    pipeData: snapshotFormData().pipeData,
    initialPressure: other.initialPressure,
    reservoirTemperature: other.reservoirTemperature,
    productionRate: other.productionRate,
    wellheadExportPressure: other.wellheadExportPressure
  })
}
function sameNumber(left, right) {
  if (left == null || right == null || left === '' || right === '') return false
  const x = Number(left), y = Number(right)
  return Number.isFinite(x) && Number.isFinite(y) &&
    Math.abs(x - y) <= 1e-9 * Math.max(1, Math.abs(x), Math.abs(y))
}

// 物性来源采用算法自身的 PVT 记录，不在本页将历史 PVT 组分与页面输入
// 强行判定为一致。实际采用的气体比重等信息记录在结果对象中，以便追溯。
function calculationMatchesForm() {
  const meta = calculationMeta.value
  const result = calculationResults.value
  if (!meta || !result || !hasTubing(formData.pipeData.wellboreStructure)) return false
  if (lastCalculatedSignature.value !== calculatedInputSignature()) return false
  if (meta.wellboreStructure !== formData.pipeData.wellboreStructure ||
      Number(meta.wellStructureCode) !== WELLBORE_STRUCTURES.indexOf(formData.pipeData.wellboreStructure) + 1 ||
      !sameNumber(meta.tubingInnerDiameterMm, formData.pipeData.tubingInnerDiameter) ||
      !sameNumber(meta.pressureMpa, formData.otherData.initialPressure) ||
      !sameNumber(meta.temperatureC, formData.otherData.reservoirTemperature) ||
      !sameNumber(meta.evaluatedRate1e4M3d, formData.otherData.productionRate) ||
      !sameNumber(result.wellheadExportPressure?.value, formData.otherData.wellheadExportPressure)) {
    return false
  }
  return true
}
// 冲蚀是可选约束：即使曾勾选，只要本次冲蚀没有有效且已核实的结果，
// 保存时也不会把它当作已生效的产量上限。
const erosionReady = computed(() => {
  const r = calculationResults.value?.erosionLimit
  const value = optionalNumber(r?.value)
  return r?.available === true && r?.verified === true &&
    value !== null && value >= 0
})
const effectiveSelectedConstraints = computed(() => ({
  ...selectedConstraints,
  erosionLimit: Boolean(selectedConstraints.erosionLimit && erosionReady.value)
}))
const erosionNotApplied = computed(() =>
  Boolean(calculationResults.value && selectedConstraints.erosionLimit &&
    !erosionReady.value))
const erosionNotAppliedMessage = computed(() => {
  if (!erosionNotApplied.value) return ''
  const why = String(calculationResults.value?.erosionLimit?.reason || '').trim()
  return '冲蚀上限未取得有效结果或尚未核实，仍可保存。' +
    '本次保存不启用冲蚀约束，产量上限按出砂上限确定。' +
    (why ? ` 原因：${why}` : '')
})

// 不再用校验状态禁用按钮：未满足条件时由点击事件给出明确原因。
const saveBlockedReason = computed(() => {
  const structure = formData.pipeData.wellboreStructure
  if (!hasTubing(structure)) return `${structure}没有油管，无法计算约束条件`
  if (isCalculating.value) return '约束条件正在计算，请等待计算完成后保存'
  const result = calculationResults.value
  const meta = calculationMeta.value
  if (!result || !meta) {
    return '当前还没有可保存的计算结果；请先点击“计算约束条件”，修改过计算参数后也需重新计算'
  }
  // 历史方案 PUT 与新建 POST 必须执行相同的输入一致性校验。
  if (!calculationMatchesForm()) {
    return '当前输入与上一次计算工况不一致；请重新点击“计算约束条件”后再保存'
  }
  if (!selectedConstraints.sandProductionLimit || !selectedConstraints.liquidLoadingLimit) {
    return '保存有效约束方案必须勾选出砂上限和积液下限'
  }
  for (const [key, label] of [
    ['sandProductionLimit', '出砂气量'],
    ['liquidLoadingLimit', '积液气量'],
    ['wellheadExportPressure', '井口外输压力']
  ]) {
    if (result[key]?.available !== true) {
      const reason = String(result[key]?.reason || '').trim()
      return `${label}未取得有效计算结果。${reason || '请重新计算'}`
    }
    if (result[key]?.verified !== true) {
      const reason = String(result[key]?.reason || '').trim()
      return `${label}计算结果尚未验证。${reason || '请检查PVT及计算参数后重新计算'}`
    }
  }
  // 冲蚀未算出不阻止保存，它会从实际生效的约束中排除。
  const range = productionRange.value
  if (!range?.complete) return '选中的约束尚未全部计算完成，请检查计算结果'
  if (!range.feasible) return '积液下限高于出砂/冲蚀上限，约束区间不可行，不能保存'
  if (range.lower == null || range.upper == null) {
    return '产量上、下限不完整，不能保存'
  }
  return ''
})
const canSave = computed(() => !saving.value && !saveBlockedReason.value)

// 与方案生成页共享本井的最新计算快照；无须依赖父组件额外转发事件。
function syncConstraintSnapshot(payload) {
  if (typeof window === 'undefined') return
  const key = scopeKey(scope())
  try {
    const storageKey = `grdp:constraints:v1:${key}`
    if (payload) window.sessionStorage.setItem(storageKey, JSON.stringify(payload))
    else window.sessionStorage.removeItem(storageKey)
    window.dispatchEvent(new CustomEvent('grdp:constraints-updated', {
      detail: { scopeKey: key }
    }))
  } catch (error) {
    console.warn('[约束条件] 同步计算快照失败，仍会通过 Vue 事件通知父组件', error)
  }
}
function invalidate(clearCurrentSnapshot = true) {
  ++requestVersion
  isCalculating.value = false
  calculationResults.value = null
  calculationMeta.value = null
  actualAlgorithmRequests.value = null
  lastCalculatedSignature.value = null
  runningCalculationSignature = null
  if (clearCurrentSnapshot) syncConstraintSnapshot(null)
  emit('constraints-invalidated')
}
watch(formData, () => {
  if (restoringRecord) return
  // 计算请求进行中修改依赖参数时，立即废弃在途结果，防止用新表单为旧结果签名。
  if (isCalculating.value && runningCalculationSignature !== null &&
      runningCalculationSignature !== calculatedInputSignature()) {
    invalidate(true)
    ElMessage.warning('计算过程中约束参数发生改变，本次在途结果已作废；请重新点击“计算约束条件”')
    return
  }
  // 对影响约束计算的字段，禁止把旧计算结果随新输入保存。
  if (calculationResults.value && lastCalculatedSignature.value !== calculatedInputSignature()) {
    invalidate(true)
  } else if (calculationResults.value && calculationMeta.value) {
    // 未影响本次计算的其它输入可以同步更新快照。
    publishResults()
  }
}, { deep: true, flush: 'sync' })
watch(() => formData.pipeData.wellboreStructure, selected => {
  if (typeof window === 'undefined' || !WELLBORE_STRUCTURES.includes(selected)) return
  try {
    window.sessionStorage.setItem(structureSelectionKey(), selected)
  } catch (error) {
    console.warn('[约束条件] 无法记住井身结构选择', error)
  }
}, { flush: 'sync' })
// 切换井时按新的井号恢复选项，不把上一口井的选项带过来。
watch(() => [props.projectId, props.gasReservoirId, props.wellName], () => {
  ++recordLoadVersion
  invalidate(false)
  currentRecordId.value = null
  currentRecordName.value = null
  constraintHistory.value = []
  restoreWellboreStructure()
  void loadHistory()
  if (props.recordId) void openRecord({ id: props.recordId })
}, { flush: 'sync' })
watch(() => props.recordId, (id) => {
  if (id) void openRecord({ id })
  else {
    ++recordLoadVersion
    currentRecordId.value = null
    currentRecordName.value = null
  }
})
function onOtherConstraintSaved(event) {
  if (event?.detail?.scopeKey && event.detail.scopeKey !== scopeKey(scope())) return
  void loadHistory()
}
onMounted(() => {
  restoreWellboreStructure()
  void loadHistory()
  if (props.recordId) void openRecord({ id: props.recordId })
  window.addEventListener('grdp:constraints-saved', onOtherConstraintSaved)
  window.addEventListener('grdp:objective-saved', onObjectiveSaved)
  syncTargetProductionFromObjective()
})
onBeforeUnmount(() => {
  unmounted = true
  ++requestVersion
  ++recordLoadVersion
  ++historyRequestVersion
  window.removeEventListener('grdp:constraints-saved', onOtherConstraintSaved)
  window.removeEventListener('grdp:objective-saved', onObjectiveSaved)
})

const productionRange = computed(() => {
  const results = calculationResults.value
  if (!results) return null
  const applied = effectiveSelectedConstraints.value
  const selected = selectedKeys.filter(key => applied[key])
  const missing = selected.filter(key => results[key]?.available !== true)
  const unverified = selected.filter(key => results[key]?.available === true && results[key]?.verified !== true)
  const lower = applied.liquidLoadingLimit && results.liquidLoadingLimit?.available === true &&
    results.liquidLoadingLimit?.verified === true
    ? results.liquidLoadingLimit.value : null
  const candidates = ['erosionLimit', 'sandProductionLimit']
    .filter(key => applied[key] &&
      results[key]?.available === true && results[key]?.verified === true)
    .map(key => optionalNumber(results[key].value))
    .filter(value => value !== null && value >= 0)
  const upper = candidates.length ? Math.min(...candidates) : null
  const feasible = lower === null || upper === null || lower <= upper
  return {
    lower, upper, feasible, missing, unverified,
    complete: applied.sandProductionLimit && applied.liquidLoadingLimit &&
      missing.filter(k => k !== 'erosionLimit').length === 0 && unverified.filter(k => k !== 'erosionLimit').length === 0
  }
})
const formatBound = value => value == null || !Number.isFinite(Number(value))
  ? '未取得' : Number(value).toLocaleString('zh-CN', { maximumFractionDigits: 4 })

function publishResults() {
  if (restoringRecord || !calculationResults.value || !calculationMeta.value) return
  const range = productionRange.value
  const cr = calculationResults.value
  const pressureReady = cr.wellheadExportPressure?.available === true &&
    cr.wellheadExportPressure?.verified === true
  const requiredReady = calculationMatchesForm() && range.complete && pressureReady
  const applied = effectiveSelectedConstraints.value
  const payload = {
    ...scope(),
    inputs: snapshotFormData(),
    selectedConstraints: { ...applied },
    optionalConstraintsNotApplied: erosionNotApplied.value
      ? [{ key: 'erosionLimit', label: '冲蚀气量',
        reason: calculationResults.value?.erosionLimit?.reason || '未取得已核实结果' }]
      : [],
    constraintResults: clone(cr),
    erosionLimit: clone(cr.erosionLimit),
    sandProductionLimit: clone(cr.sandProductionLimit),
    liquidLoadingLimit: clone(cr.liquidLoadingLimit),
    wellheadExportPressure: clone(cr.wellheadExportPressure),
    // 显式提供四个边界值：三项是计算气量阈值，一项是用户设定的井口压力边界。
    boundaryConditions: {
      erosionLimit: requiredReady && applied.erosionLimit &&
        cr.erosionLimit?.available === true && cr.erosionLimit?.verified === true
        ? cr.erosionLimit.value : null,
      sandProductionLimit: requiredReady ? cr.sandProductionLimit.value : null,
      liquidLoadingLimit: requiredReady ? cr.liquidLoadingLimit.value : null,
      wellheadExportPressure: requiredReady ? cr.wellheadExportPressure.value : null
    },
    lowerBound: requiredReady ? range.lower : null,
    upperBound: requiredReady ? range.upper : null,
    complete: Boolean(requiredReady),
    feasible: range.feasible,
    usableForPlan: Boolean(requiredReady && range.feasible),
    pending: [...range.missing, ...range.unverified, ...(pressureReady ? [] : ['wellheadExportPressure'])],
    outletPressureMpa: requiredReady ? cr.wellheadExportPressure.value : null,
    // 预测曲线只有地层压力，尚不能据此校验实际井口压力是否达到外输要求。
    pressureConstraintPendingCurve: true,
    source: clone(calculationMeta.value)
  }
  syncConstraintSnapshot(payload)
  emit('constraints-calculated', payload)
}
watch(selectedConstraints, publishResults, { deep: true, flush: 'sync' })

async function savedModelInput(api, currentScope, isErosion = false) {
  const args = isErosion ? [currentScope] : [currentScope.projectId, currentScope.gasReservoirId, currentScope.wellName]
  const listing = unwrap(await api.list(...args))
  const records = Array.isArray(listing) ? listing : (listing?.records ?? listing?.rows ?? listing?.list ?? [])
  if (!Array.isArray(records) || records.length === 0) {
    throw new Error('当前井没有该算法的基础参数记录；请先在该算法原页面保存一次输入')
  }
  const latest = [...records].sort((a, b) => Number(b.calculationNo ?? b.calculation_no ?? b.id ?? 0) -
    Number(a.calculationNo ?? a.calculation_no ?? a.id ?? 0))[0]
  if (latest?.id == null) throw new Error('算法基础记录缺少 ID')
  const detail = unwrap(await api.detail(latest.id, ...args))
  const record = detail?.record ?? detail
  const input = parseJson(record?.input_json ?? record?.inputJson ?? record?.input)
  if (!input || Array.isArray(input) || typeof input !== 'object') {
    throw new Error('最新记录没有可用的模型输入参数')
  }
  return input
}

function currentInput() {
  const currentScope = scope()
  if (!Number.isSafeInteger(currentScope.projectId) || currentScope.projectId <= 0 ||
    !Number.isSafeInteger(currentScope.gasReservoirId) || currentScope.gasReservoirId <= 0 ||
    !currentScope.wellName?.trim()) throw new Error('项目、气藏或井号不完整')
  // 只使用本次下拉框的值；无油管的结构必须在读取任何旧油管参数前停止。
  const structure = formData.pipeData.wellboreStructure
  if (!WELLBORE_STRUCTURES.includes(structure)) throw new Error('请选择有效的井身结构')
  if (!hasTubing(structure)) throw new Error(`${structure}没有油管，无法计算约束条件`)
  const gasParts = [formData.gasProperties.h2sContent, formData.gasProperties.co2Content, formData.gasProperties.n2Content]
    .map((v, i) => asNumber(v, ['H₂S含量', 'CO₂含量', 'N₂含量'][i], { zero: true }))
  if (gasParts.some(v => v > 100) || gasParts.reduce((s, n) => s + n, 0) >= 100) {
    throw new Error('非烃气体组分百分比无效')
  }
  return {
    scope: currentScope,
    wellboreStructure: structure,
    wellStructureCode: WELLBORE_STRUCTURES.indexOf(structure) + 1,
    tubingBottomMD: asNumber(formData.pipeData.tubingMdDepth, '油管下深MD', { zero: true }),
    tubingBottomTVD: asNumber(formData.pipeData.tubingTvdDepth, '油管下深TVD', { zero: true }),
    rate: asNumber(formData.otherData.productionRate, '产气量', { zero: true }),
    diameterMm: asNumber(formData.pipeData.tubingInnerDiameter, '油管内径'),
    gasGravity: asNumber(formData.gasProperties.dless, '天然气比重'),
    gasProperties: clone(formData.gasProperties),
    calcMethod: clone(formData.calcMethod),
    pressureMpa: asNumber(formData.otherData.initialPressure, '原始地层压力'),
    temperatureC: asNumber(formData.otherData.reservoirTemperature, '地层温度', { temperature: true }),
    exportPressure: asNumber(formData.otherData.wellheadExportPressure, '井口外输压力')
  }
}

function item(name, formula, value, { verified = true, reason = '', source = '', referenceValue = null } = {}) {
  const valid = value !== null && Number.isFinite(Number(value)) && Number(value) >= 0
  return {
    name, formula, value: valid ? Number(value) : null,
    available: valid, verified: valid && verified === true,
    reason, source, referenceValue,
    unit: '10⁴m³/d'
  }
}
function failed(name, formula, error) {
  return item(name, formula, null, { verified: false, reason: errorText(error), source: '本次未成功计算' })
}

async function calculateErosion(current, old, requests) {
  if (!old) throw new Error('冲蚀算法缺少历史专业参数/PVT方案')
  const pvtId = asNumber(old.pvtId, '冲蚀PVT方案ID')
  const props = unwrap(await erosionApi.properties({
    ...current.scope, pvtId, pressureMpa: current.pressureMpa, temperatureC: current.temperatureC
  }))
  const pvt = props?.properties ?? props
  if (!pvt || typeof pvt !== 'object') throw new Error('PVT接口没有返回气体物性')
  const request = {
    ...current.scope,
    pvtId,
    pvtSnapshot: pvt.pvtSnapshot ?? parseJson(old.pvtSnapshot) ?? null,
    pressureMpa: current.pressureMpa,
    temperatureC: current.temperatureC,
    actualGasRate1e4M3d: current.rate,
    tubingInnerDiameterMm: current.diameterMm,
    gasDensityKgM3: asNumber(pvt.gasDensityKgM3, '新工况气体密度'),
    liquidDensityKgM3: asNumber(pvt.liquidDensityKgM3, '新工况液体密度'),
    gasVolumeFactor: asNumber(pvt.gasVolumeFactor, '新工况气体体积系数'),
    liquidHoldupPercent: asNumber(old.liquidHoldupPercent, '冲蚀持液率', { zero: true }),
    sandContentPercent: asNumber(old.sandContentPercent, '冲蚀含砂率', { zero: true }),
    sandDensityKgM3: asNumber(old.sandDensityKgM3, '砂粒密度')
  }
  requests.erosion = clone(request)
  const rawResponse = await erosionApi.calculate(request)
  const response = unwrap(rawResponse)
  const result = response?.result ?? response
  if (!result || typeof result !== 'object') {
    throw new Error('冲蚀calculate没有返回结果对象')
  }
  if (result.success === false) throw new Error(result.reason || '冲蚀计算未成功')
  const limit = positive(result.criticalGasRate)
  if (limit === null) throw new Error('本次冲蚀calculate未返回 criticalGasRate')
  const bound = item('冲蚀气量', 'qₑ', limit, {
    verified: (result.verified == null || result.verified === true) &&
      (result.pvtVerified == null || result.pvtVerified === true),
    reason: result.reason || (result.pvtVerified === false ? '冲蚀后端未通过PVT来源校验' : ''),
    source: '本次冲蚀calculate返回的 criticalGasRate；气/液物性取冲蚀专业所选PVT，不用本页组分覆盖'
  })
  const usedPvt = parseJson(request.pvtSnapshot)
  bound.pvtIdUsed = Number(usedPvt?.pvtId ?? pvtId)
  bound.gasSpecificGravityUsed = optionalNumber(usedPvt?.gasInput?.specificGravity)
  bound.gasDensityKgM3Used = request.gasDensityKgM3
  return bound
}
async function calculateSand(current, old, requests) {
  if (!old) throw new Error('出砂算法缺少历史支撑剂/裂缝专业参数')
  const request = {
    ...current.scope,
    proppantType: old.proppantType,
    massT: asNumber(old.massT, '支撑剂质量'),
    densityGCm3: old.densityGCm3 == null ? null : asNumber(old.densityGCm3, '堆积密度'),
    halfLengthM: asNumber(old.halfLengthM, '裂缝半长'),
    closurePressureMpa: asNumber(old.closurePressureMpa, '闭合压力'),
    criticalVelocityOverrideMS: old.criticalVelocityOverrideMS == null || old.criticalVelocityOverrideMS === ''
      ? null : asNumber(old.criticalVelocityOverrideMS, '人工临界流速'),
    actualRate1e4M3d: current.rate
  }
  if (!request.proppantType) throw new Error('缺少支撑剂类型')
  requests.sand = clone(request)
  const result = unwrap(await sandProductionApi.calculate(request))
  const limit = positive(result?.criticalRate1e4M3d)
  if (limit === null) throw new Error('本次出砂calculate未返回 criticalRate1e4M3d')
  return item('出砂气量', 'qₛ', limit, {
    source: '本次出砂calculate；裂缝和闭合压力取同井已保存专业输入'
  })
}

async function calculateLiquid(current, old, requests) {
  if (!old) throw new Error('积液算法缺少已保存的日产水量/气液界面张力参数')
  const sigma = old.surfaceTensionMnM ?? old.sigma
  // 本接口的现有 Java 调度器使用 pvt.first()：读取当前井首条已保存的PVT，
  // 而不是使用传入的天然气比重或页面组分。pvtId/snapshot留空，
  // 防止积液专业历史记录选的是第2条PVT时与first()冲突。
  // 后端以自己读取的PVT执行密度、Z、Bg计算，本页绝不伪造来源快照。
  const request = {
    ...current.scope,
    qg: current.rate,
    qw: old.qw == null ? null : asNumber(old.qw, '日产水量', { zero: true }),
    pressureMpa: current.pressureMpa,
    temperatureC: current.temperatureC,
    gasSpecificGravity: current.gasGravity,
    liquidDensityKgM3: null,
    surfaceTensionMnM: asNumber(sigma, '气液界面张力'),
    tubingIdMm: current.diameterMm,
    pvtId: null,
    pvtSnapshot: null
  }
  requests.liquid = clone(request)
  const response = unwrap(await liquidLoadingApi.calculate(request))
  const result = response?.result ?? response
  if (!result || typeof result !== 'object' || result.success === false) {
    throw new Error(result?.reason || '积液calculate未返回有效结果')
  }
  // 只校验算法真正接收并使用的工况参数；不能要求后端PVT比重
  // 与本页刚编辑的比重相等，因为其算法并不消费这个覆盖字段。
  for (const [key, expected] of [
    ['qg', request.qg],
    ['pressureMpa', request.pressureMpa],
    ['temperatureC', request.temperatureC],
    ['tubingIdMm', request.tubingIdMm]
  ]) {
    if (!sameNumber(result[key], expected)) {
      throw new Error(`积液算法返回的${key}与本次工况不一致，不能保存`)
    }
  }
  const actualGasGravity = positive(result.gasSpecificGravity)
  const gasDensity = positive(result.gasDensityKgM3)
  const liquidDensity = positive(result.liquidDensityKgM3)
  const zRaw = result.zFactor ?? result.gasDeviationFactor ?? result.z
  const z = optionalNumber(zRaw)
  if (actualGasGravity === null || gasDensity === null || liquidDensity === null ||
      liquidDensity <= gasDensity || (zRaw != null && (z === null || z <= 0))) {
    throw new Error('积液算法返回的PVT气体比重/气液密度/Z因子无效')
  }
  if (result.surfaceTensionMnM != null &&
      !sameNumber(result.surfaceTensionMnM, request.surfaceTensionMnM)) {
    throw new Error('积液算法返回的界面张力与本次请求不一致')
  }
  const limit = positive(result.criticalRate1e4M3d ?? result.qCritical)
  if (limit === null) throw new Error('积液calculate未返回有效临界携液气量')
  const differsFromPage = !sameNumber(actualGasGravity, current.gasGravity)
  const bound = item('积液气量', 'qₘᵢₙ', limit, {
    verified: (result.verified == null || result.verified === true) &&
      (result.pvtVerified == null || result.pvtVerified === true),
    reason: result.reason || (differsFromPage
      ? `算法PVT比重为${actualGasGravity}，页面输入为${current.gasGravity}；实际按算法PVT计算` : ''),
    source: '本次积液calculate；气/液密度、Z因子及Bg由后端积液算法自己的首条已保存PVT提供'
  })
  bound.gasSpecificGravityUsed = actualGasGravity
  bound.gasDensityKgM3Used = gasDensity
  bound.liquidDensityKgM3Used = liquidDensity
  bound.zFactorUsed = z
  bound.pvtPolicy = 'wellbore-pvt-first-saved'
  return bound
}

async function handleCalculateConstraints() {
  if (isCalculating.value) return
  let current
  try { current = currentInput() } catch (error) {
    ElMessage.warning(errorText(error)); return
  }
  const version = ++requestVersion
  // 在发起异步请求之前固化输入，绝不能在API返回后重新给结果签署新输入的签名。
  const calculationSignature = calculatedInputSignature()
  runningCalculationSignature = calculationSignature
  isCalculating.value = true
  calculationResults.value = null
  calculationMeta.value = null
  actualAlgorithmRequests.value = null
  lastCalculatedSignature.value = null
  // 新一轮计算尚未成功时，禁止方案生成继续沿用旧的四项边界。
  syncConstraintSnapshot(null)
  emit('constraints-invalidated')
  try {
    const APIs = [erosionApi, sandProductionApi, liquidLoadingApi]
    const initial = await Promise.allSettled(APIs.map((api, i) => savedModelInput(api, current.scope, i === 0)))
    if (unmounted || version !== requestVersion) return
    const requests = { erosion: null, sand: null, liquid: null }
    const taskResults = await Promise.allSettled([
      initial[0].status === 'fulfilled'
        ? calculateErosion(current, initial[0].value, requests) : Promise.reject(initial[0].reason),
      initial[1].status === 'fulfilled'
        ? calculateSand(current, initial[1].value, requests) : Promise.reject(initial[1].reason),
      initial[2].status === 'fulfilled'
        ? calculateLiquid(current, initial[2].value, requests) : Promise.reject(initial[2].reason)
    ])
    if (unmounted || version !== requestVersion ||
        calculationSignature !== calculatedInputSignature()) return
    const boundNames = [
      ['冲蚀气量', 'qₑ'], ['出砂气量', 'qₛ'], ['积液气量', 'qₘᵢₙ']
    ]
    const bounds = taskResults.map((r, i) => r.status === 'fulfilled'
      ? r.value : failed(...boundNames[i], r.reason))
    actualAlgorithmRequests.value = clone(requests)
    calculationResults.value = {
      erosionLimit: bounds[0], sandProductionLimit: bounds[1], liquidLoadingLimit: bounds[2],
      wellheadExportPressure: {
        name: '井口外输压力', formula: 'Pₒᵤₜ', value: current.exportPressure,
        available: true, verified: true, unit: 'MPa', reason: '',
        source: '本页面输入的井口外输压力边界（非预测得到的地层压力）'
      }
    }
    calculationMeta.value = {
      evaluatedAt: new Date().toISOString(),
      calculationCondition: '按表单的原始地层压力和地层温度评价（初步筛选，非实时井口工况）',
      pressureMpa: current.pressureMpa, temperatureC: current.temperatureC,
      evaluatedRate1e4M3d: current.rate,
      wellboreStructure: current.wellboreStructure,
      wellStructureCode: current.wellStructureCode,
      tubingInnerDiameterMm: current.diameterMm,
      tubingBottomMD: current.tubingBottomMD,
      tubingBottomTVD: current.tubingBottomTVD,
      warning: '本次冲蚀/积液采用各自算法服务的PVT来源。本页面输入的组分与物性方法不会自动覆盖算法PVT；井口外输压力在方案生成阶段校验。',
      liquidPvtPolicy: 'wellbore-pvt-first-saved',
      erosionPvtPolicy: 'erosion-selected-record-pvt',
      pageGasPropertiesOverrideAlgorithmPvt: false
    }
    lastCalculatedSignature.value = calculationSignature
    publishResults()
    const range = productionRange.value
    if (!range.complete) {
      const invalid = [
        ['出砂气量', bounds[1]],
        ['积液气量', bounds[2]]
      ].find(([, item]) => !item?.available || !item?.verified)
      ElMessage.warning(invalid
        ? `${invalid[0]}未通过核验：${invalid[1]?.reason || '计算无有效结果'}`
        : '必需约束尚未完成核验，不能更新方案')
    } else if (!range.feasible) {
      ElMessage.warning('积液气量高于有效上限，当前工况不可行，不能保存')
    } else if (erosionNotApplied.value) {
      ElMessage.warning('冲蚀未取得有效结果；出砂、积液和外输压力边界已就绪，可以保存。冲蚀不参与气量上限计算。')
    } else {
      ElMessage.success('三项气量阈值及井口压力边界已同步到方案生成')
    }
  } catch (error) {
    if (!unmounted && version === requestVersion) ElMessage.error(errorText(error))
  } finally {
    if (version === requestVersion) {
      isCalculating.value = false
      runningCalculationSignature = null
    }
  }
}

async function loadHistory() {
  const version = ++historyRequestVersion
  const currentScope = scope()
  const currentKey = scopeKey(currentScope)
  if (!Number.isSafeInteger(currentScope.projectId) || currentScope.projectId <= 0 ||
      !Number.isSafeInteger(currentScope.gasReservoirId) || currentScope.gasReservoirId <= 0 ||
      !currentScope.wellName?.trim()) {
    constraintHistory.value = []
    return
  }
  historyLoading.value = true
  historyError.value = ''
  try {
    const response = await constraintRecordApi.list(
      currentScope.projectId, currentScope.gasReservoirId, currentScope.wellName)
    if (unmounted || version !== historyRequestVersion || scopeKey(scope()) !== currentKey) return
    const rows = Array.isArray(response?.data) ? response.data : (Array.isArray(response) ? response : [])
    constraintHistory.value = rows.filter(row =>
      String(row.projectId) === String(currentScope.projectId) &&
      String(row.gasReservoirId) === String(currentScope.gasReservoirId) &&
      String(row.wellName) === String(currentScope.wellName))
  } catch (error) {
    if (unmounted || version !== historyRequestVersion) return
    historyError.value = error?.message || '读取历史方案失败'
    console.warn('[约束条件] 加载历史失败：', error)
    // 保留本次操作后刚同步到界面的记录，不因历史接口暂时故障而清空列表。
  } finally {
    if (version === historyRequestVersion) historyLoading.value = false
  }
}

function deepEquivalent(a, b) {
  const normalize = value => {
    if (Array.isArray(value)) return value.map(normalize)
    if (value && typeof value === 'object') {
      const result = {}
      for (const key of Object.keys(value).sort()) result[key] = normalize(value[key])
      return result
    }
    return value
  }
  return JSON.stringify(normalize(a)) === JSON.stringify(normalize(b))
}
function assertSameScope(record) {
  if (String(record.projectId) !== String(props.projectId) ||
      String(record.gasReservoirId) !== String(props.gasReservoirId) ||
      String(record.wellName) !== String(props.wellName)) {
    throw new Error('历史方案不属于当前项目、气藏和井，已拒绝加载')
  }
}
async function openRecord(row) {
  const id = row?.id
  if (id == null || String(id).trim() === '') {
    ElMessage.warning('缺少历史记录ID')
    return
  }
  const version = ++recordLoadVersion
  const scopeBefore = scopeKey(scope())
  try {
    const response = await constraintRecordApi.detail(id)
    if (unmounted || version !== recordLoadVersion || scopeKey(scope()) !== scopeBefore) return
    const rec = response?.data || response
    if (!rec || String(rec.id) !== String(id)) throw new Error('返回的历史记录ID不一致')
    assertSameScope(rec)
    const inputs = parseJson(rec.inputsJson)
    const results = parseJson(rec.constraintResultsJson)
    const meta = parseJson(rec.calculationMetaJson)
    const selections = parseJson(rec.selectedConstraintsJson)
    const requests = parseJson(rec.algorithmRequestsJson)
    if (!inputs?.pipeData || !WELLBORE_STRUCTURES.includes(inputs.pipeData.wellboreStructure) ||
        !inputs.gasProperties || !inputs.calcMethod || !inputs.otherData) {
      throw new Error('数据库记录的完整输入参数缺失，无法加载')
    }

    // flush:'sync' 的 watcher 会立即执行，因此整批恢复期间必须暂停失效监听。
    restoringRecord = true
    try {
      for (const group of ['gasProperties', 'calcMethod', 'pipeData', 'otherData']) {
        Object.assign(formData[group], clone(initialFormData[group]))
        Object.assign(formData[group], clone(inputs[group]))
      }
      for (const key of selectedKeys) {
        selectedConstraints[key] = selections?.[key] !== false
      }
      calculationResults.value = results ? clone(results) : null
      calculationMeta.value = meta ? clone(meta) : null
      actualAlgorithmRequests.value = requests ? clone(requests) : null
      // 不能因为加载了带verified=true的历史JSON，就自动认定旧计算
      // 对应当前PVT。显示历史数值供比对，但重算之前一律禁止更新。
      lastCalculatedSignature.value = null
      currentRecordId.value = String(rec.id)
      currentRecordName.value = rec.recordName || row.recordName || `约束条件${rec.id}`
      acceptCurrentPvtAsBaseline()
    } finally {
      restoringRecord = false
    }
    if (calculationResults.value) {
      publishResults()
    }    historyVisible.value = false
    ElMessage.success(`已加载方案：${currentRecordName.value}`)
  } catch (error) {
    if (!unmounted && version === recordLoadVersion) {
      ElMessage.error('加载历史记录失败：' + (error?.message || '未知错误'))
    }
  }
}
function startNewRecord() {
  // 显式新建才取消历史ID；修改已加载记录并再次保存应当走PUT。
  currentRecordId.value = null
  currentRecordName.value = null
  ElMessage.info('已切换为新建方案，当前输入会另存为一条新记录')
}
function broadcastRecordChange(action, record) {
  if (typeof window === 'undefined') return
  window.dispatchEvent(new CustomEvent('grdp:constraints-saved', {
    detail: {
      scopeKey: scopeKey(scope()),
      projectId: Number(props.projectId),
      gasReservoirId: Number(props.gasReservoirId),
      wellName: props.wellName,
      id: String(record.id),
      recordName: record.recordName || '',
      action
    }
  }))
}
async function removeRecord(row) {
  if (saving.value || !row?.id) return
  try {
    await ElMessageBox.confirm(`确认删除方案"${row.recordName}"？`, '删除确认', {
      type: 'warning', confirmButtonText: '删除', cancelButtonText: '取消'
    })
    await constraintRecordApi.delete(
      row.id, Number(props.projectId), Number(props.gasReservoirId), props.wellName)
    ++historyRequestVersion
    constraintHistory.value = constraintHistory.value.filter(item =>
      String(item.id) !== String(row.id))
    if (String(currentRecordId.value) === String(row.id)) {
      currentRecordName.value = null
      currentRecordId.value = null
    }
    broadcastRecordChange('deleted', row)
    void loadHistory()
    ElMessage.success('已删除历史方案')
  } catch (error) {
    if (error !== 'cancel' && error?.message !== 'cancel') {
      ElMessage.error('删除失败：' + (error?.message || '未知错误'))
    }
  }
}

function buildSavePayload() {
  if (!hasTubing(formData.pipeData.wellboreStructure)) {
    throw new Error(`${formData.pipeData.wellboreStructure}没有油管，无法计算约束条件`)
  }
  if (!calculationResults.value || !calculationMeta.value) {
    throw new Error('缺少计算结果，请重新计算约束条件后保存')
  }
  if (!calculationMatchesForm()) {
    throw new Error('当前输入已修改，原计算结果不再对应这些数据，请重新计算约束条件后保存')
  }
  if (!canSave.value && !saving.value) {
    throw new Error('出砂、积液和井口压力约束尚未完成，或产量区间不可行')
  }
  const range = productionRange.value
  const cr = calculationResults.value
  const cm = calculationMeta.value
  if (!range?.feasible) {
    throw new Error('约束上下界不可行，不能保存')
  }
  if (!range.complete ||
      cr.sandProductionLimit?.available !== true || cr.sandProductionLimit?.verified !== true ||
      cr.liquidLoadingLimit?.available !== true || cr.liquidLoadingLimit?.verified !== true ||
      cr.wellheadExportPressure?.available !== true || cr.wellheadExportPressure?.verified !== true) {
    throw new Error('约束结果未验证或上下界不可行，不能保存')
  }
  const input = snapshotFormData()
  const structure = Number(formData.pipeData.wellboreStructure.match(/^情况([1-4])$/)?.[1])
  if (!structure || structure !== Number(cm.wellStructureCode)) {
    throw new Error('井身结构与本次计算不一致，请重新计算')
  }
  const numericValue = (value, label) => asNumber(value, label)
  const gasBound = (value, label) => asNumber(value, label, { zero: true })
  const sand = gasBound(cr.sandProductionLimit.value, '出砂上限')
  const liquid = gasBound(cr.liquidLoadingLimit.value, '积液下限')
  const applied = effectiveSelectedConstraints.value
  const erosion = applied.erosionLimit
    ? gasBound(cr.erosionLimit?.value, '冲蚀上限') : null
  const pressure = numericValue(formData.otherData.wellheadExportPressure, '外输压力')
  const upper = Math.min(sand, ...(erosion == null ? [] : [erosion]))
  if (liquid > upper) throw new Error('积液下限大于气量上限，不能保存')
  return {
    projectId: Number(props.projectId),
    gasReservoirId: Number(props.gasReservoirId),
    wellName: props.wellName,
    recordName: currentRecordName.value || null,
    wellboreStructure: structure,
    tubingInnerDiameterMm: numericValue(input.pipeData.tubingInnerDiameter, '油管内径'),
    erosionLimit: erosion,
    sandProductionLimit: sand,
    liquidLoadingLimit: liquid,
    wellheadExportPressure: pressure,
    lowerBound: liquid,
    upperBound: upper,
    complete: true,
    feasible: true,
    usableForPlan: true,
    inputSchemaVersion: 1,
    inputsJson: input,
    // 数据库记录的是“实际生效”的约束开关，未算出的冲蚀不会误用于方案生成。
    selectedConstraintsJson: clone(applied),
    // 保留失败的冲蚀计算原始信息，供历史方案查看原因。
    constraintResultsJson: clone(cr),
    boundaryConditionsJson: {
      erosionLimit: erosion,
      sandProductionLimit: sand,
      liquidLoadingLimit: liquid,
      wellheadExportPressure: pressure
    },
    calculationMetaJson: {
      ...clone(cm),
      erosionOriginallySelected: Boolean(selectedConstraints.erosionLimit),
      erosionActuallyApplied: Boolean(applied.erosionLimit),
      erosionNotAppliedReason: erosionNotApplied.value
        ? (cr.erosionLimit?.reason || '冲蚀没有已核实的结果') : ''
    },
    algorithmRequestsJson: clone(actualAlgorithmRequests.value),
    calculatedAt: cm.evaluatedAt
  }
}

// 更新前重新调用专业算法核对临界值。PVT在计算和保存之间发生变化时，
// 不能把旧的结果当成新的提交。核验仍以算法成功返回的实际物性为准。
async function assertAlgorithmFreshBeforeSave(payload) {
  const requests = payload.algorithmRequestsJson
  const bounds = payload.constraintResultsJson
  if (!requests?.sand || !requests?.liquid) {
    throw new Error('缺少出砂或积液算法请求记录，请先重新计算约束')
  }
  const sandResponse = unwrap(await sandProductionApi.calculate(requests.sand))
  const sand = sandResponse?.result ?? sandResponse
  if (sand?.success === false || !sameNumber(sand?.criticalRate1e4M3d, bounds.sandProductionLimit?.value)) {
    throw new Error('出砂算法的最新结果与当前约束不同，请重新计算约束后保存')
  }
  const liquidResponse = unwrap(await liquidLoadingApi.calculate(requests.liquid))
  const liquid = liquidResponse?.result ?? liquidResponse
  const liquidRate = liquid?.criticalRate1e4M3d ?? liquid?.qCritical
  if (liquid?.success === false || liquid?.verified === false || liquid?.pvtVerified === false ||
      !sameNumber(liquidRate, bounds.liquidLoadingLimit?.value) ||
      !sameNumber(liquid?.gasSpecificGravity, bounds.liquidLoadingLimit?.gasSpecificGravityUsed) ||
      !sameNumber(liquid?.gasDensityKgM3, bounds.liquidLoadingLimit?.gasDensityKgM3Used) ||
      !sameNumber(liquid?.liquidDensityKgM3, bounds.liquidLoadingLimit?.liquidDensityKgM3Used) ||
      (bounds.liquidLoadingLimit?.zFactorUsed != null &&
        !sameNumber(liquid?.zFactor ?? liquid?.gasDeviationFactor ?? liquid?.z,
          bounds.liquidLoadingLimit.zFactorUsed))) {
    throw new Error('积液算法的最新PVT物性或临界气量已变化，请重新计算约束后保存')
  }
  if (payload.selectedConstraintsJson?.erosionLimit) {
    const old = requests.erosion
    if (!old?.pvtId) throw new Error('冲蚀算法请求缺少PVT来源，请重新计算')
    const latestResponse = unwrap(await erosionApi.properties({
      projectId: payload.projectId,
      gasReservoirId: payload.gasReservoirId,
      wellName: payload.wellName,
      pvtId: old.pvtId,
      pressureMpa: old.pressureMpa,
      temperatureC: old.temperatureC
    }))
    const props = latestResponse?.properties ?? latestResponse
    const before = parseJson(old.pvtSnapshot)
    const after = parseJson(props?.pvtSnapshot)
    if (!before?.inputHash || !after?.inputHash || before.inputHash !== after.inputHash ||
        !sameNumber(props?.gasDensityKgM3, old.gasDensityKgM3) ||
        !sameNumber(props?.liquidDensityKgM3, old.liquidDensityKgM3) ||
        !sameNumber(props?.gasVolumeFactor, old.gasVolumeFactor)) {
      throw new Error('冲蚀专业PVT物性已更新，请重新计算约束后保存')
    }
    const erosionResponse = unwrap(await erosionApi.calculate(old))
    const erosion = erosionResponse?.result ?? erosionResponse
    if (erosion?.success === false || erosion?.verified === false || erosion?.pvtVerified === false ||
        !sameNumber(erosion?.criticalGasRate, bounds.erosionLimit?.value)) {
      throw new Error('冲蚀算法的最新结果发生变化，请重新计算约束后保存')
    }
  }
}

async function handleSave() {
  if (saving.value) return
  saveFeedbackVisible.value = true
  if (saveBlockedReason.value) {
    ElMessage.warning(saveBlockedReason.value)
    return
  }
  let payload
  try { payload = buildSavePayload() } catch (error) {
    ElMessage.warning(error?.message || '当前约束条件不能保存')
    return
  }
  // 历史记录JSON可能将布尔值写成字符串/数字；后端严格使用Boolean.TRUE。
  // PUT/POST前按与Java完全一致的类型要求再次校验，杜绝422才暴露问题。
  for (const key of ['sandProductionLimit', 'liquidLoadingLimit', 'wellheadExportPressure']) {
    const item = payload.constraintResultsJson?.[key]
    if (item?.available !== true || item?.verified !== true) {
      ElMessage.warning(`${key}的available/verified不是布尔true，请重新计算后更新方案`)
      return
    }
  }
  const idToUpdate = currentRecordId.value
  const capturedScope = scopeKey(scope())
  const capturedSignature = JSON.stringify(payload.inputsJson)
  saving.value = true
  try {
    await assertAlgorithmFreshBeforeSave(payload)
    if (unmounted || scopeKey(scope()) !== capturedScope ||
        !calculationMatchesForm() ||
        JSON.stringify(payload.inputsJson) !== JSON.stringify(snapshotFormData())) {
      throw new Error('算法校验期间方案输入已发生变化，请重新计算后更新')
    }
    const response = idToUpdate
      ? await constraintRecordApi.update(idToUpdate, payload)
      : await constraintRecordApi.save(payload)
    const saved = response?.data || response
    if (!saved?.id ||
        (idToUpdate && String(saved.id) !== String(idToUpdate))) {
      throw new Error('保存接口没有返回正确的记录ID，不能确认更新结果')
    }
    assertSameScope(saved)
    const serverInputs = parseJson(saved.inputsJson)
    const inputsMatchDatabase = deepEquivalent(serverInputs, payload.inputsJson)

    if (unmounted || scopeKey(scope()) !== capturedScope) return
    const savedId = String(saved.id)
    currentRecordId.value = savedId
    currentRecordName.value = saved.recordName || payload.recordName || `约束条件${savedId}`

    // 本地即时更新列表，无须刷新页面或等待历史查询完成。
    ++historyRequestVersion
    const list = constraintHistory.value.filter(item => String(item.id) !== savedId)
    constraintHistory.value = [{ ...saved, id: savedId }, ...list]
    broadcastRecordChange(idToUpdate ? 'updated' : 'created', {
      ...saved, id: savedId, recordName: currentRecordName.value
    })
    void loadHistory()

    const suffix = JSON.stringify(snapshotFormData()) !== capturedSignature
      ? '（保存期间表单又发生了变化，数据库保存的是点击时的数据）' : ''
    saveFeedbackVisible.value = false
    if (!inputsMatchDatabase) {
      ElMessage.error('数据库已写入记录，但回读的完整输入与点击保存时不一致；请核对历史记录详情')
    } else {
      ElMessage.success(`${idToUpdate ? '已更新原记录' : '已新建约束方案'}：${currentRecordName.value}${suffix}`)
    }
  } catch (error) {
    if (!unmounted) {
      const reason = errorText(error)
      if (String(reason).includes('liquidLoadingLimit') &&
          String(reason).includes('尚未验证')) {
        console.error('[约束条件] 后端拒绝积液验证标志，请核对请求与Java读取字段：', {
          liquidLoadingLimit: payload.constraintResultsJson?.liquidLoadingLimit,
          jsonType: typeof payload.constraintResultsJson?.liquidLoadingLimit?.verified,
          expectedLimit: payload.liquidLoadingLimit,
          recordId: idToUpdate
        })
      }
      ElMessage.error('保存失败：' + reason)
    }
  } finally {
    saving.value = false
  }
}

</script>

